-- Disposable local PostgreSQL only. Never run this on the hosted project.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema storage;
create table auth.users(id uuid primary key default gen_random_uuid(), email text, email_confirmed_at timestamptz, created_at timestamptz default now(), last_sign_in_at timestamptz, raw_app_meta_data jsonb default '{}');
create table auth.identities(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), provider text);
create function auth.uid() returns uuid language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub',nullif(current_setting('request.jwt.claim.sub',true),''))::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) $$;
create table public.profiles(id uuid primary key references auth.users(id), email text, first_name text, last_name text, avatar_url text);
create table public.ai_generations(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), image_path text not null, prompt text not null, caption text not null, created_at timestamptz default now());
create table public.generation_votes(generation_id uuid references public.ai_generations(id) on delete cascade, user_id uuid references auth.users(id), vote int not null check(vote in(-1,1)), created_at timestamptz default now(), primary key(generation_id,user_id));
create table storage.buckets(id text primary key, public boolean default false);
insert into storage.buckets values('generated-media',false);
create table storage.objects(id uuid primary key default gen_random_uuid(), bucket_id text references storage.buckets(id), name text);
create function storage.foldername(path text) returns text[] language sql as $$ select string_to_array(path,'/') $$;
grant usage on schema public,auth,storage to anon,authenticated;
grant select,insert,update,delete on all tables in schema public,storage to authenticated;
grant select on all tables in schema public,storage to anon;
alter table public.profiles enable row level security;
create policy "Own profile" on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.ai_generations enable row level security;
create policy "Own post writes" on public.ai_generations for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.generation_votes enable row level security;
create policy "Signed in vote reads" on public.generation_votes for select to authenticated using(true);
create policy "Own vote writes" on public.generation_votes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table storage.objects enable row level security;
create policy "Read images" on storage.objects for select to authenticated using(true);
create policy "Own image inserts" on storage.objects for insert to authenticated with check((storage.foldername(name))[1]=auth.uid()::text);
create policy "Own image deletes" on storage.objects for delete to authenticated using((storage.foldername(name))[1]=auth.uid()::text);
